/*
 * parse - lexer: reads CA<pid> character by character, records the source
 * line for the listing and the error markers, and turns the text into
 * tokens.  Tokens generated by the lowering actions are queued in front of
 * the file and read first.  A stack of lexer modes selects how text is
 * scanned (statements or header text) and whether the semantic actions
 * run.
 */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "parse_int.h"

/* a lexer mode */
typedef struct {
    int active;                        /* semantic actions are called */
    int (*scan)(char *text);
    void (*recover)(char *text);
} lexer_mode_t;

/* input */
char g_parse_line[LINE_MAX_CHARS + 1];   /* text of the current line */
char g_parse_marker[LINE_MAX_CHARS + 1]; /* '^' under the error columns */
FILE *g_parse_in;
int g_parse_in_open;
int g_parse_in_line;                   /* current line number */
int g_parse_in_col;                    /* characters of the line read so far */
static int g_in_eof;

/* lexer modes and the token queue */
static const lexer_mode_t *g_mode_stack[MODE_STACK_DEPTH];
static int g_mode_top;
static int g_mode_level;
list_t g_parse_queue;                  /* tokens to read before the file */
static char g_token_text[TOKEN_TEXT_SIZE + 1];

/* =========================================================================
 * Scanner
 * ========================================================================= */

/* add a character to the line buffer; tabs become blanks up to
 * the next multiple of eight */
static void record_char(int c)
{
    if (g_parse_in_col > 0xff) {
        parse_fatal_error(ERR_LINE_TOO_LONG, "");
    }
    if ((char)c != '\t') {
        if (g_parse_marker[g_parse_in_col] != '^') {
            g_parse_marker[g_parse_in_col] = ' ';
        }
        g_parse_line[g_parse_in_col] = (char)c;
        g_parse_in_col++;
        return;
    }
    int stop = (g_parse_in_col + 8) / 8 * 8;
    while (g_parse_in_col < stop) {
        if (g_parse_marker[g_parse_in_col] != '^') {
            g_parse_marker[g_parse_in_col] = ' ';
        }
        g_parse_line[g_parse_in_col] = ' ';
        g_parse_in_col++;
    }
}

/* skip blanks and line ends */
static int skip_blanks(int stop_at_line_end)
{
    if (g_in_eof) {
        return TOK_EOF;
    }
    for (;;) {
        int c = parse_read_char(g_parse_in);
        if (c == EOF || c == '\n') {
            parse_end_of_line();
            if (c == EOF) {
                g_in_eof = 1;
                return TOK_EOF;
            }
            if (stop_at_line_end) {
                return TOK_EOL;
            }
            continue;
        }
        if (!is_space(c)) {
            parse_unread_char(c, g_parse_in);
            return 0;
        }
        record_char(c);
    }
}

/* read text up to `stop` (which is consumed) */
static int read_until(char *text, int stop, int stop_at_blank, int discard)
{
    size_t n = 0;
    if (!g_parse_in_open) {
        parse_fatal_error(1014, "");
    }
    if (g_in_eof) {
        return TOK_TEXT;
    }
    text[0] = '\0';
    for (;;) {
        int c = parse_read_char(g_parse_in);
        if (c == '\n' || c == EOF) {
            parse_end_of_line();
            if (c == EOF) {
                g_in_eof = 1;
                return TOK_TEXT;
            }
        }
        if (c != '\n') {
            record_char(c);
        }
        if (c == stop) {
            return TOK_TEXT;
        }
        if (is_space(c) && stop_at_blank) {
            return TOK_TEXT;
        }
        if (!discard && n < TOKEN_TEXT_SIZE - 1) {
            text[n++] = (char)c;
        }
        text[n] = '\0';
    }
}

/* skip the rest of a line that starts with '$' */
static void skip_line(void)
{
    int c;
    while ((c = parse_read_char(g_parse_in)) != '\n' && c != EOF) {
        record_char(c);
    }
    parse_end_of_line();
    if (c == EOF) {
        g_in_eof = 1;
    }
}

/* called after a '/'; skips a comment if one starts here */
static int skip_comment(void)
{
    int c = parse_read_char(g_parse_in);
    if (c != '*' && c != '/') {
        parse_unread_char(c, g_parse_in);
        return 0;
    }
    record_char(c);
    if (c == '/') {
        /* There is no end-of-file check: at the end of the file the line
         * buffer fills up and "line exceeds maximum length" ends the run. */
        while ((c = parse_read_char(g_parse_in)) != '\n') {
            record_char(c);
        }
        record_char('\n');
        parse_end_of_line();
        return 1;
    }
    int star = 0;
    for (;;) {
        c = parse_read_char(g_parse_in);
        if (c == '\n' || c == EOF) {
            parse_end_of_line();
            if (c == EOF) {
                parse_fatal_error(ERR_EOF_IN_COMMENT, "");
            }
        } else {
            record_char(c);
        }
        if (c == '*') {
            star = 1;
            continue;
        }
        if (c == '/' && star) {
            return 1;
        }
        star = 0;
    }
}

/* scan one token of a statement.  Identifiers and numbers are
 * one class of word: a word of digits only is a number, a word that ends
 * in a digit is an indexed name. */
static int scan_token(char *text)
{
    int c;
    int kind;
    int last;
    size_t n = 0;
    for (;;) {
        for (;;) {
            if (!g_parse_in_open) {
                parse_fatal_error(1001, "");
            }
            if (g_in_eof) {
                return TOK_EOF;
            }
            skip_blanks(0);
            c = parse_read_char(g_parse_in);
            if (c == EOF) {
                g_in_eof = 1;
                return TOK_EOF;
            }
            record_char(c);
            if (c != '$' || g_parse_in_col != 1) {
                break;
            }
            skip_line();
        }
        if (c != '/') {
            text[n++] = (char)c;
            text[n] = '\0';
        }
        if (is_alpha(c) || c == '_') {
            kind = TOK_IDENT;
            break;
        }
        if (is_digit(c)) {
            kind = TOK_NUMBER;
            break;
        }
        if (c != '/') {
            if (c == '=') {
                c = parse_read_char(g_parse_in);
                if (c == '=') {
                    text[n++] = '=';
                    text[n] = '\0';
                } else {
                    parse_unread_char(c, g_parse_in);
                }
            }
            return TOK_PUNCT;
        }
        /* A '/' that does not start a comment leaves the text of the
         * previous token in the buffer. */
        if (!skip_comment()) {
            return TOK_PUNCT;
        }
    }
    last = kind;
    for (;;) {
        c = parse_read_char(g_parse_in);
        if (c == EOF) {
            g_in_eof = 1;
            return TOK_EOF;
        }
        if (is_alpha(c) || c == '_') {
            last = TOK_IDENT;
        } else if (is_digit(c)) {
            last = TOK_NUMBER;
        } else {
            break;
        }
        record_char(c);
        if (n < TOKEN_TEXT_SIZE - 1) {
            text[n++] = (char)c;
        }
        if (kind == TOK_NUMBER && last == TOK_IDENT) {
            kind = TOK_IDENT;
        }
    }
    parse_unread_char(c, g_parse_in);
    text[n] = '\0';
    if (kind == TOK_IDENT) {
        return last == TOK_NUMBER ? TOK_IDENT_NUM : TOK_IDENT;
    }
    return last == TOK_NUMBER ? TOK_NUMBER : TOK_IDENT;
}

/* the text of a header item up to ';' */
static int scan_header_text(char *text)
{
    skip_blanks(0);
    return read_until(text, ';', 0, 0);
}

/* after a syntax error skip to the next ';' */
static void recover_statement(char *text)
{
    skip_blanks(0);
    read_until(text, ';', 0, 1);
}

/* after a syntax error in header text skip to the end of the line */
static void recover_line(char *text)
{
    read_until(text, '\n', 0, 0);
}

static const lexer_mode_t k_mode_inactive = { 0, NULL, NULL };
static const lexer_mode_t k_mode_statement = { 1, scan_token, recover_statement };
static const lexer_mode_t k_mode_header_text = { 1, scan_header_text, recover_line };

void parse_lex_reset(void)
{
    memset(g_parse_line, 0, sizeof(g_parse_line));
    memset(g_parse_marker, 0, sizeof(g_parse_marker));
    g_parse_in = NULL;
    g_parse_in_open = 0;
    g_parse_in_line = 0;
    g_parse_in_col = 0;
    g_in_eof = 0;
    memset(g_mode_stack, 0, sizeof(g_mode_stack));
    g_mode_stack[0] = &k_mode_inactive;
    g_mode_top = 0;
    g_mode_level = 0;
    parse_list_init(&g_parse_queue);
    g_token_text[0] = '\0';
}

/* open the input file `name` and scan statements from it */
void parse_lex_open(const char *name)
{
    g_mode_stack[g_mode_top] = &k_mode_statement;
    g_mode_level = 0;
    g_parse_in_open = 1;
    g_parse_in = parse_open_file(name, "rt");
    if (g_parse_in == NULL) {
        parse_fatal_error(ERR_OPEN, name);
    }
    g_parse_in_line = 1;
    g_parse_in_col = 0;
    g_in_eof = 0;
}

/* the current mode level scans header text up to ';' */
void parse_lex_header_text_mode(void)
{
    g_mode_stack[g_mode_top] = &k_mode_header_text;
}

/* skip the rest of the statement after a syntax error, the way the
 * current mode does it; `text` is scratch space */
void parse_lex_recover(char *text)
{
    const lexer_mode_t *mode = g_mode_stack[g_mode_top];
    if (mode->recover != NULL) {
        mode->recover(text);
    }
}

int parse_actions_enabled(void)
{
    return g_mode_stack[g_mode_top]->active;
}

/* enter a new lexer mode level; it starts inactive (no actions) */
void parse_push_mode(void)
{
    if (g_mode_top == MODE_STACK_DEPTH - 1) {
        parse_fatal_error(1011, "");
    } else {
        g_mode_top++;
    }
    g_mode_stack[g_mode_top] = &k_mode_inactive;
    g_mode_level++;
}

void parse_pop_mode(void)
{
    if (g_mode_top == 0) {
        parse_fatal_error(1012, "");
    } else {
        g_mode_top--;
    }
    g_mode_level--;
}

/* the next token, from the queue of generated tokens if there
 * are any, else from the file */
token_t *parse_next_token(void)
{
    token_t *tok;
    const char *text;
    int code;
    int queued = 0;
    const keyword_t *keyword;

    if (g_parse_queue.head == NULL) {
        const lexer_mode_t *mode = g_mode_stack[g_mode_top];
        if (mode->scan == NULL) {
            parse_fatal_error(1009, "");
        }
        code = mode->scan(g_token_text);
        text = g_token_text;
        tok = parse_token_alloc();
    } else {
        tok = parse_list_pop_front(&g_parse_queue);
        code = tok->type;
        text = (tok->flags & (TF_SYMBOL | TF_NUMBER)) ? NULL : tok->u.text;
        queued = 1;
    }
    switch (code) {
    case TOK_IDENT:
        keyword = parse_find_keyword(text);
        if (keyword != NULL) {
            tok->u.text = keyword->name;
            tok->type = (uint8_t)keyword->id;
            return tok;
        }
        break;
    case TOK_BAD:
        parse_fatal_error(ERR_SYNTAX, text);
        break;
    case TOK_UNKNOWN:
        parse_error_at(ERR_SYNTAX, text);
        return tok;
    case TOK_PUNCT:
        keyword = parse_find_punctuation(text);
        if (keyword != NULL) {
            tok->u.text = keyword->name;
            tok->type = (uint8_t)keyword->id;
            return tok;
        }
        break;
    case TOK_EOF:
        tok->u.any = NULL;
        tok->type = TOK_EOF;
        return tok;
    default:
        break;
    }
    if (!queued) {
        tok->u.text = parse_intern(text);
    }
    tok->type = (uint8_t)code;
    return tok;
}

const char *parse_token_text(const token_t *tok)
{
    return (tok->flags & (TF_SYMBOL | TF_NUMBER)) ? NULL : tok->u.text;
}
